statement.shape:
SHAPE { select tp.TaskProcessId , tp.Description , tp.TaskProcessTypeCode , tp.SuppliedResourceValue , tp.SuppliedResourceTypeCode , tp.CreatorId , tp.CreatedDate , tp.LastUpdateId , tp.LastUpdateDate from taskprocess tp
inner join RelTaskProcessTask rtpt on tp.taskprocessid = rtpt.taskprocessid inner join tasks t on t.taskid = rtpt.taskid
} APPEND({ select trv.FieldCode, trv.SourceProviderId, trv.SourceProviderCode, trv.FieldValue from taskrelatedvalue trv inner join taskprocess tp on trv.sourceProviderId = tp.taskprocessid and trv.sourceProviderCode = 1
inner join RelTaskProcessTask rtpt on tp.taskprocessid = rtpt.taskprocessid inner join tasks t on t.taskid = rtpt.taskid
}RELATE TaskProcessId to SourceProviderId ) as RelatedValue

SHAPE { select t.TaskId, t.TaskTypeCode, t.PrimaryFieldCode, t.AssignedOnDate, t.StartedOnDate, t.CompletedOnDate, t.TaskStatusCode, t.AssigneeId, t.ClientTaskId, t.ClientTaskDescription, t.CreatorId, t.CreatedDate, t.LastUpdateDate, t.LastUpdateId from taskprocess tp inner join RelTaskProcessTask rtpt on tp.taskprocessid = rtpt.taskprocessid inner join tasks t on t.taskid = rtpt.taskid
} APPEND({ select trv.FieldCode, trv.SourceProviderId, trv.SourceProviderCode, trv.FieldValue from taskrelatedvalue trv inner join tasks t on trv.sourceProviderId = t.taskid and trv.sourceProviderCode = 2 inner join RelTaskProcessTask rtpt on t.taskid = rtpt.taskid inner join taskprocess tp on tp.taskprocessid = rtpt.taskprocessid
}RELATE TaskId to SourceProviderId ) as RelatedValue
